+@page "/catalog"
+@namespace sv_99c938229ebf4b55a7b8774ad04d5c30.Components.Pages.Catalog
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h3 class="mb-4">Product Catalog</h3>
+
+<div class="row">
+    @* Sidebar filters *@
+    <div class="col-lg-3 mb-3">
+        <CatalogFilters Categories="@categories" OnFilterApply="HandleFilterApply" />
+    </div>
+
+    @* Main content *@
+    <div class="col-lg-9">
+        @if (isLoading)
+        {
+            <div class="d-flex justify-content-center align-items-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading...</span>
+                </div>
+            </div>
+        }
+        else if (errorMessage is not null)
+        {
+            <div class="alert alert-danger" role="alert">
+                <strong>Error:</strong> @errorMessage
+                <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryLoad">Retry</button>
+            </div>
+        }
+        else
+        {
+            <CatalogToolbar SortBy="@sortBy"
+                            Page="@currentPage"
+                            PageSize="@pageSize"
+                            TotalCount="@totalCount"
+                            OnSortChanged="HandleSortChanged" />
+
+            @if (products.Count == 0)
+            {
+                <div class="text-center py-5 text-muted">
+                    <h5>No products found</h5>
+                    <p>Try adjusting your filters or search criteria.</p>
+                </div>
+            }
+            else
+            {
+                <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3">
+                    @foreach (var product in products)
+                    {
+                        <div class="col">
+                            <ProductCard Product="@product"
+                                         OnProductSelected="HandleProductSelected"
+                                         OnAddToCart="HandleAddToCart" />
+                        </div>
+                    }
+                </div>
+
+                <CatalogPagination CurrentPage="@currentPage"
+                                   TotalPages="@totalPages"
+                                   OnPageChanged="HandlePageChanged" />
+            }
+        }
+    </div>
+</div>
+
+@code {
+    [Parameter]
+    public EventCallback<int> OnProductSelected { get; set; }
+
+    private List<Product> products = new();
+    private List<string>? categories;
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private int pageSize = 12;
+    private int totalCount;
+    private int totalPages;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            var categoriesTask = categories is null
+                ? ProductService.GetCategoriesAsync()
+                : Task.FromResult(categories);
+            var searchTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
+
+            await Task.WhenAll(categoriesTask, searchTask);
+
+            categories = await categoriesTask;
+            var result = await searchTask;
+
+            products = result.Items;
+            totalCount = result.TotalCount;
+            totalPages = (int)Math.Ceiling((double)totalCount / pageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleFilterApply(ProductFilter filter)
+    {
+        currentFilter = filter;
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task HandleSortChanged(string newSort)
+    {
+        sortBy = newSort;
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        currentPage = page;
+        await LoadDataAsync();
+    }
+
+    private async Task HandleProductSelected(int productId)
+    {
+        await OnProductSelected.InvokeAsync(productId);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        return Task.CompletedTask;
+    }
+
+    private async Task RetryLoad()
+    {
+        await LoadDataAsync();
+    }
+}
